<?php if($e['published_at']||(!$e['exceptions']&&!empty($s['draft_generated_at']))):?><small><a href="payroll-slip.php?entry=<?=(int)$e['id']?>"><?=$e['published_at']?'View payslip':'Draft payslip'?></a></small><?php endif;?></td></tr>
<tr><td colspan="10"><details><summary>Calculation details · <?=h($e['name'])?></summary>
